  for (const [key, value] of Object.entries(record.fields ?? {})) {
    if (
      normalized.has(key.toLowerCase().replace(/[^a-z0-9]/g, "")) &&
      ((typeof value === "string" && value.trim()) || typeof value === "number")
    )
      return String(value);
  }
  return undefined;

