export function collectAllBlocks(graph: WorkflowGraph): WorkflowBlock[] {
  const blocks: WorkflowBlock[] = [];
  function recurse(g: WorkflowGraph) {
    for (const b of g.blocks) {
      blocks.push(b);
      if (b.inner) recurse(b.inner);
    }
  }
  recurse(graph);
  return blocks;
}

